const schema = `
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, phone TEXT UNIQUE, email TEXT UNIQUE, full_name TEXT, status TEXT NOT NULL DEFAULT 'active', role TEXT NOT NULL DEFAULT 'customer', password_hash TEXT, avatar_url TEXT, avatar_media_id TEXT, last_login_at TEXT, last_login_ip TEXT, marketing_email_opt_in INTEGER NOT NULL DEFAULT 1, marketing_sms_opt_in INTEGER NOT NULL DEFAULT 1, marketing_in_app_opt_in INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS otp_challenges (id TEXT PRIMARY KEY, identity TEXT NOT NULL, channel TEXT NOT NULL, code_hash TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, max_attempts INTEGER NOT NULL DEFAULT 5, expires_at TEXT NOT NULL, consumed_at TEXT, request_ip TEXT, purpose TEXT NOT NULL DEFAULT 'auth', user_id TEXT, target_identity TEXT, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS otp_identity_created_idx ON otp_challenges(identity, created_at);
CREATE TABLE IF NOT EXISTS sessions (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, refresh_jti TEXT UNIQUE NOT NULL, user_agent TEXT, ip TEXT, expires_at TEXT NOT NULL, revoked_at TEXT, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS sessions_user_idx ON sessions(user_id, created_at);
CREATE TABLE IF NOT EXISTS bookings (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, vertical TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', provider_ref TEXT, request TEXT NOT NULL, response TEXT, owner_id TEXT, internal_note TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS bookings_user_idx ON bookings(user_id, created_at);
CREATE INDEX IF NOT EXISTS bookings_status_idx ON bookings(status, updated_at);
CREATE TABLE IF NOT EXISTS booking_events (id TEXT PRIMARY KEY, booking_id TEXT NOT NULL, actor_id TEXT, action TEXT NOT NULL, from_status TEXT, to_status TEXT, note TEXT, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS booking_events_booking_idx ON booking_events(booking_id, created_at);
CREATE TABLE IF NOT EXISTS tours (id TEXT PRIMARY KEY, slug TEXT UNIQUE NOT NULL, title TEXT NOT NULL, country TEXT NOT NULL, tour_type TEXT NOT NULL, destinations TEXT NOT NULL, duration_days INTEGER NOT NULL, duration_nights INTEGER NOT NULL, description TEXT NOT NULL DEFAULT '', image_url TEXT NOT NULL DEFAULT '', media_id TEXT, metadata TEXT NOT NULL DEFAULT '{}', price_bdt REAL NOT NULL, status TEXT NOT NULL DEFAULT 'draft', featured INTEGER NOT NULL DEFAULT 0, created_by TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS tours_filter_idx ON tours(status, country, tour_type, price_bdt);
CREATE TABLE IF NOT EXISTS payments (id TEXT PRIMARY KEY, booking_id TEXT NOT NULL, user_id TEXT NOT NULL, provider TEXT NOT NULL, amount REAL NOT NULL, currency TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'created', transaction_ref TEXT, provider_payload TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS support_tickets (id TEXT PRIMARY KEY, user_id TEXT, name TEXT NOT NULL, mobile TEXT NOT NULL, email TEXT NOT NULL, subject TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'open', created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS notifications (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, title TEXT NOT NULL, message TEXT NOT NULL, channels TEXT NOT NULL, read_at TEXT, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS notifications_user_idx ON notifications(user_id, created_at);
CREATE TABLE IF NOT EXISTS audit_logs (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id TEXT, action TEXT NOT NULL, ip TEXT, user_agent TEXT, metadata TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT, is_secret INTEGER NOT NULL DEFAULT 0, updated_by TEXT, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS content_items (id TEXT PRIMARY KEY, type TEXT NOT NULL, slug TEXT NOT NULL, title TEXT NOT NULL, subtitle TEXT, description TEXT, image_url TEXT, media_id TEXT, metadata TEXT NOT NULL DEFAULT '{}', status TEXT NOT NULL DEFAULT 'draft', sort_order INTEGER NOT NULL DEFAULT 0, created_by TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(type, slug));
CREATE INDEX IF NOT EXISTS content_filter_idx ON content_items(type, status, sort_order, updated_at);
CREATE TABLE IF NOT EXISTS media_assets (id TEXT PRIMARY KEY, public_id TEXT UNIQUE NOT NULL, secure_url TEXT NOT NULL, original_filename TEXT NOT NULL, mime_type TEXT NOT NULL, format TEXT NOT NULL, width INTEGER, height INTEGER, bytes INTEGER NOT NULL, folder TEXT NOT NULL, alt_text TEXT, uploaded_by TEXT, status TEXT NOT NULL DEFAULT 'active', created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS media_assets_folder_idx ON media_assets(folder, status, created_at);
CREATE TABLE IF NOT EXISTS admin_navigation (id TEXT PRIMARY KEY, group_name TEXT NOT NULL, parent_id TEXT, label TEXT NOT NULL, route TEXT NOT NULL, icon TEXT NOT NULL, permission TEXT, sort_order INTEGER NOT NULL DEFAULT 0, visible INTEGER NOT NULL DEFAULT 1, enabled INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS admin_navigation_order_idx ON admin_navigation(group_name, sort_order);
CREATE TABLE IF NOT EXISTS travel_agents (id TEXT PRIMARY KEY, full_name TEXT NOT NULL, photo_url TEXT, media_id TEXT, job_title TEXT, department TEXT, phone TEXT, whatsapp TEXT, email TEXT, office_location TEXT, short_bio TEXT, full_description TEXT, languages TEXT NOT NULL DEFAULT '[]', experience_years INTEGER, specialization TEXT, working_hours TEXT, status TEXT NOT NULL DEFAULT 'active', featured INTEGER NOT NULL DEFAULT 0, display_order INTEGER NOT NULL DEFAULT 0, created_by TEXT, updated_by TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS travel_agents_status_idx ON travel_agents(status, featured, display_order);
CREATE TABLE IF NOT EXISTS campaign_templates (id TEXT PRIMARY KEY, name TEXT NOT NULL, type TEXT NOT NULL, subject TEXT, content TEXT NOT NULL, metadata TEXT NOT NULL DEFAULT '{}', status TEXT NOT NULL DEFAULT 'active', created_by TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS customer_segments (id TEXT PRIMARY KEY, name TEXT NOT NULL, description TEXT, rules TEXT NOT NULL DEFAULT '{}', status TEXT NOT NULL DEFAULT 'active', created_by TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS campaigns (id TEXT PRIMARY KEY, name TEXT NOT NULL, channels TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'draft', subject TEXT, preheader TEXT, sender_name TEXT, sender_email TEXT, email_html TEXT, email_text TEXT, sms_message TEXT, web_title TEXT, web_message TEXT, web_cta_text TEXT, web_cta_url TEXT, segment_id TEXT, recipient_filter TEXT NOT NULL DEFAULT '{}', scheduled_at TEXT, timezone TEXT, total_recipients INTEGER NOT NULL DEFAULT 0, queued_count INTEGER NOT NULL DEFAULT 0, sent_count INTEGER NOT NULL DEFAULT 0, delivered_count INTEGER NOT NULL DEFAULT 0, failed_count INTEGER NOT NULL DEFAULT 0, read_count INTEGER NOT NULL DEFAULT 0, created_by TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS campaign_recipients (id TEXT PRIMARY KEY, campaign_id TEXT NOT NULL, user_id TEXT NOT NULL, channel TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'queued', provider_ref TEXT, error TEXT, attempts INTEGER NOT NULL DEFAULT 0, queued_at TEXT, sent_at TEXT, delivered_at TEXT, read_at TEXT, created_at TEXT NOT NULL, UNIQUE(campaign_id,user_id,channel));
CREATE INDEX IF NOT EXISTS campaign_recipients_queue_idx ON campaign_recipients(campaign_id, status, channel);
CREATE TABLE IF NOT EXISTS support_messages (id TEXT PRIMARY KEY, ticket_id TEXT NOT NULL, author_id TEXT, author_type TEXT NOT NULL DEFAULT 'system', message TEXT NOT NULL, internal INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS support_messages_ticket_idx ON support_messages(ticket_id, created_at);
CREATE TABLE IF NOT EXISTS customer_notes (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, author_id TEXT, note TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS customer_notes_user_idx ON customer_notes(user_id, created_at);
`;

