  async getSetting(key: string) { const row = this.db.prepare('SELECT value,is_secret FROM settings WHERE key=?').get(key) as Row | undefined; if (!row?.value) return undefined; return row.is_secret ? decryptSecret(row.value) : String(row.value); }
  async getAdminSettings() { const rows = this.db.prepare('SELECT key,value,is_secret,updated_by,updated_at FROM settings ORDER BY key').all() as Row[]; return rows.map(row => ({ key: row.key, configured: Boolean(row.value), secret: Boolean(row.is_secret), updatedBy: row.updated_by ?? undefined, updatedAt: row.updated_at ?? undefined, ...(row.is_secret ? { masked: maskSecret(row.value) } : { value: row.value ?? '' }) })); }
  async updateSettings(patch: SettingPatch, updatedBy: string) { const statement = this.db.prepare('INSERT INTO settings(key,value,is_secret,updated_by,updated_at) VALUES(?,?,?,?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value,is_secret=excluded.is_secret,updated_by=excluded.updated_by,updated_at=excluded.updated_at'); const transaction = this.db.transaction((entries: [string, string | undefined][]) => { for (const [key, raw] of entries) { if (raw === undefined) continue; const secret = SECRET_SETTING_KEYS.has(key); statement.run(key, secret ? encryptSecret(raw) : raw, secret ? 1 : 0, updatedBy, now()); } }); transaction(Object.entries(patch)); }
  async getServiceVisibility() { return SERVICE_DEFINITIONS.map(definition => { const row = this.db.prepare('SELECT value,updated_by,updated_at FROM settings WHERE key=?').get(`service_${definition.key}_status`) as Row | undefined; const feature = this.db.prepare('SELECT value FROM settings WHERE key=?').get(`feature_${definition.key}`) as Row | undefined; const status = row?.value && ['active','hidden','maintenance','archived'].includes(String(row.value)) ? String(row.value) as ServiceStatus : feature?.value === 'false' ? 'hidden' : 'active'; const updatedBy = row?.updated_by ? this.db.prepare('SELECT * FROM users WHERE id=?').get(row.updated_by) as Row | undefined : undefined; return { ...definition, status, updatedBy: updatedBy ? (updatedBy.full_name || updatedBy.email || updatedBy.phone || updatedBy.id) : undefined, updatedAt: row?.updated_at ?? undefined }; }); }
  async updateServiceVisibility(key: ServiceKey, status: ServiceStatus, updatedBy: string) { const definition = SERVICE_DEFINITIONS.find(item => item.key === key); if (!definition) throw new Error('Unknown service'); const updatedAt = now(); const value = status; this.db.prepare('INSERT INTO settings(key,value,is_secret,updated_by,updated_at) VALUES(?,?,?,?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value,is_secret=0,updated_by=excluded.updated_by,updated_at=excluded.updated_at').run(`service_${key}_status`, value, 0, updatedBy, updatedAt); this.db.prepare('INSERT INTO settings(key,value,is_secret,updated_by,updated_at) VALUES(?,?,?,?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value,is_secret=0,updated_by=excluded.updated_by,updated_at=excluded.updated_at').run(`feature_${key}`, status === 'hidden' || status === 'archived' ? 'false' : 'true', 0, updatedBy, updatedAt); const user = this.db.prepare('SELECT * FROM users WHERE id=?').get(updatedBy) as Row | undefined; return { ...definition, status, updatedBy: user ? (user.full_name || user.email || user.phone || user.id) : undefined, updatedAt }; }

