  private campaignUserRows(filter: Record<string, unknown>, userIds?: string[]) { const where:string[]=["u.status='active'"]; const params:any[]=[]; if(userIds?.length){where.push(`u.id IN (${userIds.map(()=>'?').join(',')})`);params.push(...userIds);} if(filter.neverBooked===true)where.push('NOT EXISTS (SELECT 1 FROM bookings b0 WHERE b0.user_id=u.id)'); if(typeof filter.lastBookingDays==='number'){where.push("NOT EXISTS (SELECT 1 FROM bookings b1 WHERE b1.user_id=u.id AND b1.created_at>=datetime('now',?))");params.push(`-${Math.max(0,Math.floor(filter.lastBookingDays))} days`);} if(typeof filter.minSpent==='number'){where.push("(SELECT COALESCE(SUM(p.amount),0) FROM payments p WHERE p.user_id=u.id AND p.status IN ('paid','partially_refunded'))>=?");params.push(filter.minSpent);} if(typeof filter.service==='string'&&filter.service){where.push('EXISTS (SELECT 1 FROM bookings b2 WHERE b2.user_id=u.id AND b2.vertical=?)');params.push(filter.service);} if(typeof filter.bookingStatus==='string'&&filter.bookingStatus){where.push('EXISTS (SELECT 1 FROM bookings b3 WHERE b3.user_id=u.id AND b3.status=?)');params.push(filter.bookingStatus);} /* Channel opt-outs are applied per channel when recipient rows are created. */ const rows=this.db.prepare(`SELECT u.* FROM users u WHERE ${where.join(' AND ')} ORDER BY u.created_at ASC`).all(...params) as Row[]; return rows; }
